const raw = $input.first().json;
const isManual = !raw.headers;
const p = raw.body || raw;
const sample = 'Should a seed-stage startup with 6 engineers adopt microservices, or stay with a modular monolith?';
const question = (typeof p.question === 'string' && p.question.trim()) ? p.question.trim() : (isManual ? sample : '');

const thr = Number(p.agreementThreshold);
const panel = Array.isArray(p.panel) ? p.panel.filter(x => x && x.name && x.model) : [];

return [{
  json: {
    questionValid: !!question,
    validationError: question ? null : 'Request body must include a non-empty question string',
    taskId: p.taskId || ('arb-' + Date.now()),
    question,
    context: typeof p.context === 'string' ? p.context : '',
    criteria: typeof p.criteria === 'string' ? p.criteria : '',
    reqThreshold: thr > 0 && thr <= 1 ? thr : 0,
    reqMaxRounds: Math.min(4, Number(p.maxRounds) || 0),
    reqPanel: panel,
    startedAt: new Date().toISOString(),
    round: 1,
    positions: [],
    history: [],
    agreementByRound: [],
    lastDisagreements: [],
    lastEval: null,
    panelCostUsd: 0,
    judgeCostUsd: 0,
    arbiterCostUsd: 0,
    arbiter: null
  }
}];

const s = $input.first().json;
let panel = [];
if (Array.isArray(s.reqPanel) && s.reqPanel.length) panel = s.reqPanel;
else { try { panel = JSON.parse(s.panelConfig); } catch (e) {} }
panel = panel.filter(p => p && p.name && p.model);
if (panel.length < 2) throw new Error('The panel needs at least two panelists');

const shape = JSON.stringify({ answer: 'your full answer', keyClaims: ['claims your answer depends on'], confidence: 0.0, reasoning: 'brief justification', changedMind: false });

return panel.map(p => {
  const system = 'You are ' + (p.persona || 'an expert') + ', one independent member of an expert panel. Give your own best answer and do not hedge just to be agreeable. confidence is your honest probability (0 to 1) that your answer is correct. Respond ONLY with valid JSON, no prose, matching exactly this shape: ' + shape;
  let user = 'Question: ' + s.question + (s.context ? '\n\nContext:\n' + s.context : '') + (s.criteria ? '\n\nDecision criteria: ' + s.criteria : '');
  if (s.round > 1) {
    const mine = s.positions.find(x => x.panelist === p.name);
    const others = s.positions.filter(x => x.panelist !== p.name && x.status === 'ok');
    user += '\n\nThis is debate round ' + s.round + '. Your previous answer: ' + (mine && mine.answer ? mine.answer : '(none)')
      + '\n\nOther panelists:\n' + others.map(o => '- ' + o.panelist + ' (confidence ' + o.confidence + '): ' + o.answer + ' | key claims: ' + (o.keyClaims || []).join('; ')).join('\n')
      + '\n\nPoints of disagreement:\n' + (s.lastDisagreements.length ? s.lastDisagreements.map(d => '- ' + d.topic).join('\n') : '- not specified')
      + '\n\nReconsider honestly. Change your answer only if persuaded by evidence or sound reasoning, never just because others disagree. Set changedMind to true only if your answer changed.';
  }
  return { json: {
    panelist: p.name, model: p.model, weight: Number(p.weight) || 1, round: s.round,
    anthropicApiUrl: s.anthropicApiUrl,
    request: { model: p.model, max_tokens: 1200, system, messages: [{ role: 'user', content: user }] },
    state: s
  } };
});

const items = $('Build Panel Requests').all();
const resps = $input.all();
const state = items[0].json.state;

let catalog = [];
try { catalog = JSON.parse(state.modelCatalog); } catch (e) {}

let roundCost = 0;
const positions = items.map((it, i) => {
  const meta = it.json;
  const r = (resps[i] && resps[i].json) || {};
  const price = catalog.find(m => m.id === meta.model) || { inputPer1M: 0, outputPer1M: 0 };
  const u = r.usage || {};
  const inTok = u.input_tokens || 0, outTok = u.output_tokens || 0;
  const cost = inTok / 1e6 * price.inputPer1M + outTok / 1e6 * price.outputPer1M;
  roundCost += cost;

  let d = null, err = null;
  try {
    if (r.error || !Array.isArray(r.content)) throw new Error(r.error && r.error.message ? r.error.message : 'no content returned');
    const raw = r.content.filter(b => b.type === 'text').map(b => b.text).join('').replace(/```json|```/g, '');
    const m = raw.match(/\{[\s\S]*\}/);
    d = JSON.parse(m ? m[0] : raw);
  } catch (e) { err = e.message; }
  const ok = !!(d && typeof d.answer === 'string' && d.answer.trim());
  return {
    panelist: meta.panelist, model: meta.model, weight: meta.weight, round: meta.round,
    status: ok ? 'ok' : 'failed', error: ok ? null : (err || 'missing answer'),
    answer: ok ? d.answer.trim() : '',
    keyClaims: ok && Array.isArray(d.keyClaims) ? d.keyClaims.map(String) : [],
    confidence: ok && typeof d.confidence === 'number' ? Math.min(1, Math.max(0, d.confidence)) : null,
    reasoning: ok ? String(d.reasoning || '').slice(0, 800) : '',
    changedMind: ok ? !!d.changedMind : false,
    inputTokens: inTok, outputTokens: outTok, costUsd: Math.round(cost * 1e6) / 1e6
  };
});

return [{ json: { ...state, positions, history: [...state.history, { round: state.round, positions }], panelCostUsd: state.panelCostUsd + roundCost } }];

const s = $input.first().json;
const valid = s.positions.filter(p => p.status === 'ok');
const list = valid.map(p => '[' + p.panelist + '] weight ' + p.weight + ', confidence ' + p.confidence + '\nAnswer: ' + p.answer + '\nKey claims: ' + p.keyClaims.join('; ')).join('\n\n') || 'No valid answers.';

const shape = JSON.stringify({
  clusters: [{ label: 'short name of the position', members: ['Panelist names'], position: 'the shared position in one or two sentences' }],
  consensusAnswer: 'the best statement of the largest cluster position',
  disagreements: [{ topic: 'specific point of disagreement', positions: [{ panelist: 'name', claim: 'what they claim' }] }],
  disagreementType: 'factual | interpretive | values | none'
});
const system = 'You are a neutral adjudicator. Group the panelists answers into clusters of substantively equivalent positions; ignore wording, length and style differences, but split clusters when the conclusions or recommendations actually differ. Every panelist belongs to exactly one cluster. List the specific points on which the clusters disagree. Do not judge who is right. Respond ONLY with valid JSON, no prose, matching exactly this shape: ' + shape;

return [{ json: { ...s, agreementRequest: { model: s.judgeModel, max_tokens: 1200, system, messages: [{ role: 'user', content: 'Question: ' + s.question + '\n\nPanel answers (round ' + s.round + '):\n\n' + list }] } } }];

const s = $('Build Agreement Request').first().json;
const { agreementRequest, ...state } = s;
const resp = $input.first().json;

let catalog = [];
try { catalog = JSON.parse(state.modelCatalog); } catch (e) {}
const jp = catalog.find(m => m.id === state.judgeModel) || { inputPer1M: 0, outputPer1M: 0 };
const u = resp.usage || {};
const judgeCost = (u.input_tokens || 0) / 1e6 * jp.inputPer1M + (u.output_tokens || 0) / 1e6 * jp.outputPer1M;

const valid = state.positions.filter(p => p.status === 'ok');
const weightOf = n => (valid.find(p => p.panelist === n) || {}).weight || 0;
const totalW = valid.reduce((a, p) => a + p.weight, 0);

let parsed = null;
try {
  const raw = resp.content.filter(b => b.type === 'text').map(b => b.text).join('').replace(/```json|```/g, '');
  const m = raw.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(m ? m[0] : raw);
} catch (e) { parsed = null; }

// Agreement is computed in code from panelist weights, not trusted from the model
const seen = new Set();
const clusters = ((parsed && parsed.clusters) || []).map(c => {
  const members = (c.members || []).filter(n => valid.some(p => p.panelist === n) && !seen.has(n));
  members.forEach(n => seen.add(n));
  return { label: c.label || '', members, position: c.position || '', weight: members.reduce((a, n) => a + weightOf(n), 0) };
}).filter(c => c.members.length);
valid.filter(p => !seen.has(p.panelist)).forEach(p => clusters.push({ label: 'unclustered', members: [p.panelist], position: p.answer, weight: p.weight }));

clusters.sort((a, b) => b.weight - a.weight);
const top = clusters[0];
const parseFailed = !parsed;
const agreement = (valid.length >= 2 && !parseFailed && totalW > 0 && top) ? Math.round(top.weight / totalW * 1000) / 1000 : 0;

const threshold = state.reqThreshold || state.agreementThreshold;
const maxRounds = state.reqMaxRounds || state.maxRounds;
const consensus = valid.length >= 2 && agreement >= threshold;

let consensusAnswer = (parsed && parsed.consensusAnswer) || '';
if (!consensusAnswer && top) {
  const lead = valid.filter(p => top.members.includes(p.panelist)).sort((a, b) => b.weight - a.weight)[0];
  consensusAnswer = lead ? lead.answer : '';
}
const disagreements = (parsed && Array.isArray(parsed.disagreements)) ? parsed.disagreements : [];

let nextAction = 'finalize';
if (!consensus) nextAction = (valid.length >= 1 && state.round < maxRounds) ? 'debate' : 'arbitrate';

const lastEval = { agreement, threshold, consensus, consensusAnswer, disagreementType: (parsed && parsed.disagreementType) || 'unknown', clusters, parseFailed, validPanelists: valid.length };

return [{ json: {
  ...state, lastEval, nextAction, maxRoundsEffective: maxRounds,
  lastDisagreements: disagreements,
  agreementByRound: [...state.agreementByRound, { round: state.round, agreement, consensus, disagreementType: lastEval.disagreementType, clusters: clusters.map(c => ({ label: c.label, members: c.members, position: c.position })) }],
  round: nextAction === 'debate' ? state.round + 1 : state.round,
  judgeCostUsd: state.judgeCostUsd + judgeCost
} }];

const s = $input.first().json;
const rounds = s.history.map(h => 'ROUND ' + h.round + ':
' + h.positions.filter(p => p.status === 'ok').map(p =>
  '[' + p.panelist + ' | ' + p.model + ' | weight ' + p.weight + ' | confidence ' + p.confidence + (p.changedMind ? ' | changed mind' : '') + ']
Answer: ' + p.answer + '
Key claims: ' + p.keyClaims.join('; ') + '
Reasoning: ' + p.reasoning).join('

')).join('

====

');
const disputes = s.lastDisagreements.map(d => '- ' + d.topic + ': ' + (d.positions || []).map(x => x.panelist + ' says ' + x.claim).join(' / ')).join('
') || '- not specified';

const shape = JSON.stringify({ verdict: 'the final answer to the question', rationale: 'why this is best supported, including how the disputed points were resolved', adoptedPosition: 'a panelist name or synthesis', confidence: 0.0, keyDissent: 'the strongest remaining opposing view, or empty', needsHumanReview: false, verifiedClaims: ['claims you verified or corrected'] });
const system = 'You are the final arbiter for a panel of AI models that could not agree. Decide on the strength of evidence and reasoning, not by majority vote, panelist confidence or weight alone (weights are a mild prior). ' + (s.arbiterWebSearch ? 'Use web search to verify disputed factual claims when that would change the verdict. ' : '') + 'If the disagreement is a matter of values or the evidence is genuinely inconclusive, give the best-supported answer, state the uncertainty in the rationale and set needsHumanReview to true. confidence is your probability that the verdict is correct. Respond ONLY with valid JSON, no prose, matching exactly this shape: ' + shape;
const user = 'Question: ' + s.question + (s.context ? '

Context:
' + s.context : '') + (s.criteria ? '

Decision criteria: ' + s.criteria : '') + '

Panel history:

' + rounds + '

Remaining points of disagreement:
' + disputes;

const req = { model: s.arbiterModel, max_tokens: 2000, system, messages: [{ role: 'user', content: user }] };
if (s.arbiterWebSearch) req.tools = [{ type: 'web_search_20250305', name: 'web_search', max_uses: 3 }];
return [{ json: { ...s, arbiterRequest: req } }];

const s = $('Build Arbiter Request').first().json;
const { arbiterRequest, ...state } = s;
const resp = $input.first().json;

let catalog = [];
try { catalog = JSON.parse(state.modelCatalog); } catch (e) {}
const ap = catalog.find(m => m.id === state.arbiterModel) || { inputPer1M: 0, outputPer1M: 0 };
const u = resp.usage || {};
const cost = (u.input_tokens || 0) / 1e6 * ap.inputPer1M + (u.output_tokens || 0) / 1e6 * ap.outputPer1M;

let d = null;
try {
  const raw = resp.content.filter(b => b.type === 'text').map(b => b.text).join('').replace(/```json|```/g, '');
  const m = raw.match(/\{[\s\S]*\}/);
  d = JSON.parse(m ? m[0] : raw);
  if (!d.verdict) d = null;
} catch (e) { d = null; }

let arbiter;
if (d) {
  const conf = typeof d.confidence === 'number' ? Math.min(1, Math.max(0, d.confidence)) : 0.5;
  arbiter = {
    method: 'arbiter_verdict', verdict: String(d.verdict), rationale: String(d.rationale || ''), adoptedPosition: d.adoptedPosition || 'synthesis',
    confidence: conf, keyDissent: String(d.keyDissent || ''), verifiedClaims: Array.isArray(d.verifiedClaims) ? d.verifiedClaims.map(String) : [],
    needsHumanReview: !!d.needsHumanReview || conf < state.arbiterConfidenceThreshold
  };
} else {
  // Fallback: highest weight x confidence among the latest valid answers, always flagged for human review
  const valid = state.positions.filter(p => p.status === 'ok').sort((a, b) => (b.weight * (b.confidence || 0.5)) - (a.weight * (a.confidence || 0.5)));
  const best = valid[0];
  arbiter = {
    method: 'fallback_weighted_pick', verdict: best ? best.answer : '', rationale: 'The arbiter response could not be used, so the highest weight-times-confidence panel answer is provisional.',
    adoptedPosition: best ? best.panelist : null, confidence: best ? (best.confidence || 0.5) * 0.5 : 0, keyDissent: '', verifiedClaims: [], needsHumanReview: true
  };
}
return [{ json: { ...state, arbiter, arbiterCostUsd: state.arbiterCostUsd + cost } }];

const s = $input.first().json;
const round6 = n => Math.round(n * 1e6) / 1e6;
const ev = s.lastEval || {};
const consensus = !!ev.consensus && !s.arbiter;

let finalAnswer = '', decisionMethod = '', needsHumanReview = false, status = 'completed';
if (consensus) {
  finalAnswer = ev.consensusAnswer;
  decisionMethod = s.round === 1 ? 'consensus_round_1' : 'consensus_after_debate';
} else if (s.arbiter) {
  finalAnswer = s.arbiter.verdict;
  decisionMethod = s.arbiter.method;
  needsHumanReview = s.arbiter.needsHumanReview;
}
if (!finalAnswer) { status = 'error'; finalAnswer = 'No answer could be produced: the panel returned no usable answers.'; needsHumanReview = true; decisionMethod = 'none'; }

const totalCostUsd = s.panelCostUsd + s.judgeCostUsd + s.arbiterCostUsd;
const lean = p => ({ panelist: p.panelist, model: p.model, status: p.status, answer: p.answer, confidence: p.confidence, changedMind: p.changedMind, error: p.error });
const finalAgreement = ev.agreement === undefined ? null : ev.agreement;

const whatsappText = '\u2696\uFE0F Arbitration needs human review\n\nQuestion: ' + s.question.slice(0, 200)
  + '\nAgreement: ' + (finalAgreement === null ? 'n/a' : Math.round(finalAgreement * 100) + '%') + ' after ' + s.round + ' round(s)'
  + '\nProvisional answer: ' + String(finalAnswer).slice(0, 700)
  + (s.arbiter && s.arbiter.keyDissent ? '\nMain dissent: ' + s.arbiter.keyDissent.slice(0, 300) : '');

return [{ json: {
  needsHumanReview,
  whatsappText,
  whatsappBusinessPhoneId: s.whatsappBusinessPhoneId,
  whatsappRecipientPhone: s.whatsappRecipientPhone,
  webhookResponse: {
    taskId: s.taskId, question: s.question, status, finalAnswer, decisionMethod, needsHumanReview,
    agreement: { final: finalAgreement, threshold: ev.threshold === undefined ? null : ev.threshold, disagreementType: ev.disagreementType || null, byRound: s.agreementByRound },
    roundsRun: s.history.length,
    arbiter: s.arbiter ? { model: s.arbiterModel, confidence: s.arbiter.confidence, adoptedPosition: s.arbiter.adoptedPosition, rationale: s.arbiter.rationale, keyDissent: s.arbiter.keyDissent, verifiedClaims: s.arbiter.verifiedClaims } : null,
    remainingDisagreements: consensus && finalAgreement === 1 ? [] : s.lastDisagreements,
    positionsByRound: s.history.map(h => ({ round: h.round, positions: h.positions.map(lean) })),
    cost: { panelUsd: round6(s.panelCostUsd), adjudicatorUsd: round6(s.judgeCostUsd), arbiterUsd: round6(s.arbiterCostUsd), totalUsd: round6(totalCostUsd) },
    durationMs: Date.now() - new Date(s.startedAt).getTime()
  }
} }];
